#include <iostream>
#include <vector>
#include <algorithm>
#include <utility>
using namespace std;

using ll = long long;
using pii = pair<int, int>;
using pll = pair<ll, ll>;
using vi = vector<int>;
using vll = vector<ll>;
using vpi = vector<pii>;
using vpl = vector<pll>;
using matrix = vector<vll>;

const ll MOD = 1000000007;

inline void update_min(ll& a, ll b) { if (a > b) a = b; }
inline void update_max(ll& a, ll b) { if (a < b) a = b; }

ll N, K;
vi base_digits;
matrix global_trans;
matrix base_matrix[60][30], precomputed_prefix[60][30], precomputed_suffix[60][30];
ll final_answer;

matrix multiply_matrices(const matrix& A, const matrix& B) {
    ll n = A.size();
    matrix C(n, vll(n, 0));
    for (ll i = 0; i < n; ++i) {
        for (ll k = 0; k < n; ++k) {
            if (A[i][k]) {
                for (ll j = 0; j < n; ++j) {
                    C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD;
                }
            }
        }
    }
    return C;
}

matrix cyclic_shift(const matrix& input, int shift_amount) {
    ll n = input.size();
    matrix output(n, vll(n, 0));
    for (ll i = 0; i < n; ++i) {
        for (ll j = 0; j < n; ++j) {
            if (input[i][j]) {
                if (i == j) output[i][j] = input[i][j];
                else output[i][(j + shift_amount) % K] = input[i][j];
            }
        }
    }
    return output;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> N >> K;

    while (N > 0) {
        base_digits.push_back(N % K);
        N /= K;
    }

    for (int idx = 0; idx < K; ++idx) {
        base_matrix[0][idx].resize(K + 1);
        for (int row = 0; row <= K; ++row) {
            base_matrix[0][idx][row].resize(K + 1, 0);
        }
        for (int row = 0; row <= K; ++row) {
            base_matrix[0][idx][row][row] = 1;
        }
        for (int row = 0; row <= K; ++row) {
            base_matrix[0][idx][row][idx] = 1;
        }
    }

    for (int level = 1; level < (int)base_digits.size(); ++level) {
        precomputed_prefix[level - 1][0] = base_matrix[level - 1][0];
        for (int col = 1; col < K; ++col) {
            precomputed_prefix[level - 1][col] = multiply_matrices(precomputed_prefix[level - 1][col - 1], base_matrix[level - 1][col]);
        }

        precomputed_suffix[level - 1][K - 1] = base_matrix[level - 1][K - 1];
        for (int col = K - 2; col >= 0; --col) {
            precomputed_suffix[level - 1][col] = multiply_matrices(base_matrix[level - 1][col], precomputed_suffix[level - 1][col + 1]);
        }

        base_matrix[level][0] = precomputed_prefix[level - 1][K - 1];
        for (int col = 1; col < K; ++col) {
            base_matrix[level][col] = multiply_matrices(precomputed_suffix[level - 1][col], precomputed_prefix[level - 1][col - 1]);
        }
    }

    global_trans.resize(K + 1);
    for (int row = 0; row <= K; ++row) {
        global_trans[row].resize(K + 1, 0);
    }
    for (int row = 0; row <= K; ++row) {
        global_trans[row][row] = 1;
    }

    int cumulative_sum = 0;
    for (int pos = (int)base_digits.size() - 1; pos >= 0; --pos) {
        int digit_val = base_digits[pos];
        for (int step = 0; step < digit_val; ++step) {
            global_trans = multiply_matrices(global_trans, base_matrix[pos][cumulative_sum]);
            cumulative_sum++;
            if (cumulative_sum >= K) cumulative_sum -= K;
        }
    }

    final_answer = 1;
    for (int col = 0; col < K; ++col) {
        final_answer = (final_answer + global_trans[K][col]) % MOD;
    }

    cout << final_answer << '\n';
    return 0;
}
